import {mergeAccountSync} from './sync-model.js';
import {catalog,rune,championName,runeSignature,validatePage,refreshCatalog,SHARDS,SHARD_ROWS} from './catalog.js';
import {KEY,VERSION,DIVISIONS,TIERS,uid,clone,seed,migrate,validate,integer,number,profileURL,totals,rankAt,rankScore,stats,interval,filtered,percent} from './model.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>v===null||v===undefined?'—':typeof v==='number'?v.toLocaleString('en-US',{maximumFractionDigits:d}):esc(v),signed=v=>v===null?'—':(v>=0?'+':'')+fmt(v),wr=v=>v===null?'—':fmt(v)+'%',date=t=>new Date(t).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}),day=t=>new Date(t).toLocaleDateString('en-CA'),inputTime=t=>{const d=new Date(t);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,19);};
const btn=(label,action,id='',cls='secondary small')=>`<button type="button" class="button ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const opt=(v,label,selected)=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(label)}</option>`;
const empty=(title,sub,action='')=>`<div class="empty"><strong>${title}</strong>${sub}${action?'<div style="margin-top:15px">'+action+'</div>':''}</div>`;
const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div>${body}</section>`;
const metric=(label,value,note,cls='')=>`<div class="metric"><div class="metric-label">${label}<span>↗</span></div><div class="metric-value ${cls}">${value}</div><div class="metric-note">${note}</div></div>`;
const routes=[['overview','◈','Overview'],['accounts','▤','Accounts'],['strategies','⚑','Strategy lab'],['history','≡','Match history'],['sessions','◷','Sessions'],['insights','◇','Insights'],['settings','⚙','Data & settings']];
let runeDraft=null,syncPending=null,syncBusy=false,connectionStatus=null;
let state,blocked=false,previous=null,page=0,sort='rank',search='',f={season:'',account:'',strategy:'',region:'',patch:'',rank:'',from:'',to:''},minSample=5;
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));else {const old=localStorage.getItem('jhin_tracker_v3');state=old?migrate(JSON.parse(old)):seed(await (await fetch('./legacy-seed.json')).json());localStorage.setItem(KEY,JSON.stringify(state));}}
catch(e){blocked=true;state=seed(await (await fetch('./legacy-seed.json')).json());$('#save-status').textContent='Storage needs attention';console.error('Workspace load failed',e);}
f.season=state.season;
const getRoute=()=>routes.some(r=>r[0]===location.hash.slice(1))?location.hash.slice(1):'overview';
function toast(msg,undo=false){$('#toast').innerHTML=`<span>${esc(msg)}</span>${undo?'<button data-action="undo">Undo</button>':''}`;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),undo?12000:5000);}
function persist(next,message){if(blocked)throw Error('Saving is paused to protect existing data. Open Data & settings to recover or download a backup.');validate(next);const serialized=JSON.stringify(next);try{localStorage.setItem(KEY,serialized);}catch{throw Error('Could not save. Browser storage may be full or disabled. Your previous data is unchanged. Export a backup from Data & settings.');}previous=clone(state);state=next;$('#save-status').textContent='Saved on this browser';render();if(message)toast(message,true);}
function mutate(fn,msg){const next=clone(state);fn(next);persist(next,msg);}
const matches=()=>filtered(state,f),account=id=>state.accounts.find(a=>a.id===id),strategy=id=>state.strategies.find(t=>t.id===id),nameStrategy=id=>strategy(id)?.name||'Unassigned';
function download(value,name){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download(state,`jhin-atelier-${new Date().toISOString().slice(0,10)}.json`);toast('Backup downloaded. Keep a copy outside this browser.');}
function dialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal();}
const input=(name,label,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" value="${esc(value??'')}" type="${type}" ${type==='datetime-local'?'step="1"':''} ${attrs}></label>`;
const select=(name,label,options)=>`<label>${label}<select name="${name}">${options}</select></label>`;
const area=(name,label,value='',attrs='')=>`<label ${attrs}>${label}<textarea name="${name}" maxlength="5000">${esc(value)}</textarea></label>`;
const actions=(text='Save')=>`<div class="form-error" role="alert"></div><div class="form-actions">${btn('Cancel','close','','secondary')}<button class="button primary" type="submit">${text}</button></div>`;
const ranks=(value,none='Unranked')=>opt('',none,value)+DIVISIONS.map(r=>opt(r,r,value)).join('');
function renderFilters(){if(!['overview','history','strategies','insights'].includes(getRoute())){$('#filters').innerHTML='';return;}const seasons=[...new Set([state.season,...state.accounts.map(a=>a.baselineSeason),...state.matches.map(m=>m.season)])].sort().reverse();$('#filters').innerHTML=`<div class="filters">${filterSelect('season','All seasons',seasons.map(x=>[x,x]))}${filterSelect('account','All accounts',state.accounts.map(a=>[a.id,a.name]))}${filterSelect('strategy','All strategies',state.strategies.map(a=>[a.id,a.name]))}${filterSelect('region','All servers',[...new Set(state.accounts.map(a=>a.region))].map(x=>[x,x]))}${filterSelect('patch','All patches',[...new Set(state.matches.map(m=>m.patch).filter(Boolean))].sort().map(x=>[x,x]))}${filterSelect('rank','All starting ranks',TIERS.map(x=>[x,x]).concat([['Master','Master'],['Grandmaster','Grandmaster'],['Challenger','Challenger']]))}<input aria-label="From date" title="From date" type="date" data-filter="from" value="${f.from}"><input aria-label="To date" title="To date" type="date" data-filter="to" value="${f.to}">${btn('Reset','filters')}<span class="filter-hint">${matches().length} tracked matches · starting balances excluded</span></div>`;}
function filterSelect(key,label,options){return `<select data-filter="${key}" aria-label="${label}">${opt('',label,f[key])}${options.map(([v,l])=>opt(v,l,f[key])).join('')}</select>`;}
function heading(kicker,title,sub,action=''){$('#page-title').innerHTML=`<div class="page-heading"><div><div class="kicker">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function render(){const route=getRoute();$('#nav').innerHTML=routes.map(([id,icon,label])=>`<a class="nav-link ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}</a>`).join('');$('#season-label').textContent='SEASON '+state.season;renderFilters();const views={overview,accounts,strategies,history,sessions,insights,settings};views[route]();if(blocked)$('#content').insertAdjacentHTML('afterbegin','<div class="notice red">Existing storage could not be loaded or written. Saving is paused. Open Data & settings to download the stored data and recover it. The visible accounts are fallback starting data.</div>');}
function overview(){heading('YOUR RANKED JOURNEY','Every game, <em>a study.</em>','Track the climb. Find your edge. Make the next four shots count.');const m=matches(),s=stats(m);const active=state.sessions.find(x=>x.end===null);const recent=[...m].sort((a,b)=>b.ts-a.ts).slice(0,5);const streak=[...state.matches].filter(m=>m.result!=='remake').sort((a,b)=>b.ts-a.ts).slice(0,3);$('#content').innerHTML=`${streak.length===3&&streak.every(m=>m.result==='loss')?'<div class="notice red">Three consecutive losses across your accounts. A short break might help you reset.</div>':''}<section class="hero"><div><div class="kicker">ONE CHAMPION. MANY WAYS TO CLIMB.</div><h2>The climb is your canvas.</h2><p>${active?'Session in progress: '+esc(active.name)+'. Log each match to capture the full picture.':'Link each account once, then fetch your recent Jhin games. Save your rune pages to discover which setups work for you.'}</p>${btn(active?'View sessions →':'View accounts & sync →',active?'go-sessions':'go-accounts','','gold')}</div><div class="hero-art"><svg class="mask" viewBox="0 0 120 160" aria-hidden="true"><defs><linearGradient id="maskgold" x2="1" y2="1"><stop stop-color="#f1deb1"/><stop offset="1" stop-color="#8b8155"/></linearGradient></defs><path d="M27 15Q62-4 98 23L94 93Q85 131 62 151Q35 139 23 105L16 47Z" fill="url(#maskgold)"/><path d="M29 18L53 64 28 91 23 104 16 47Z" fill="#b4ad84"/><path d="M52 19L69 58 58 94 68 128 62 151 52 114 46 82 58 57Z" fill="#777b58" opacity=".65"/><path d="M28 58Q39 52 52 65L43 76 31 71Z" fill="#182019"/><path d="M70 61Q83 48 93 56L87 74 72 73Z" fill="#182019"/><path d="M42 107Q64 114 82 98L72 123 56 127Z" fill="#333b29"/><path d="M39 107L76 104M47 115L73 112" stroke="#d6cca2" stroke-width="3"/><path d="M83 24L76 44M91 29L84 44" stroke="#343d28" stroke-width="2"/><circle cx="83" cy="64" r="3" fill="#d4e4a5"/></svg></div></section><div class="metrics">${metric('TRACKED WIN RATE',wr(s.wr),`${s.w} wins / ${s.l} losses`,s.wr>=50?'positive':'')}${metric('AGGREGATE KDA',fmt(s.kda),'Calculated from complete K / D / A','gold-text')}${metric('CS PER MINUTE',fmt(s.csMin),'Calculated from CS and game duration','positive')}${metric('MATCHES STUDIED',fmt(s.n,0),`${new Set(m.map(x=>x.accountId)).size} accounts in this selection`)}</div><div class="grid-two">${panel('The shape of your climb',`<div class="panel-body">${chart(m)}</div>`,'<small>Recorded LP or verified rank snapshots</small>')}${panel('Recent performances',recent.length?recent.map(recentRow).join(''):empty('Your next game starts the story.','No recorded matches in this selection.',btn('Log your first match','match','','gold small')),`<a class="text-btn" href="#history">View all ↗</a>`)}</div>${panel('Your accounts',accountTable(state.accounts.filter(a=>!a.archived).sort(rankSort).slice(0,6)),`<a class="text-btn" href="#accounts">All ${state.accounts.length} accounts ↗</a>`)}<div class="help">Sync fetches recent ranked solo/duo Jhin games. Rank estimates use recorded LP and your latest checkpoint. Add a checkpoint after promotions, demotions or resets.</div>`;}
function recentRow(m){return `<div class="list-row"><div class="result-icon ${m.result==='loss'?'loss':''}">${m.result==='win'?'W':m.result==='loss'?'L':'R'}</div><div class="grow"><strong>${esc(account(m.accountId)?.name)}</strong><small>${esc(nameStrategy(m.strategyId))} · ${m.enemy?'vs '+esc(m.enemy)+' · ':''}${date(m.ts)}</small></div><div class="list-right"><strong class="${m.lp>=0?'positive':'negative'}">${signed(m.lp)} LP</strong><small>${m.duration?fmt(m.duration)+' min':'No duration'}</small></div></div>`;}
function chart(list){const m=[...list].filter(m=>m.lp!==null&&m.result!=='remake').sort((a,b)=>a.ts-b.ts);if(!m.length)return checkpointChart();const colors=['#b3d786','#ddc48a','#8dbcc1','#c09dc9','#e4a48d','#a8b7e3'];const ids=[...new Set(m.map(m=>m.accountId))];const series=ids.map((id,i)=>{let n=0;return {id,color:colors[i%colors.length],points:[{x:0,y:0},...m.filter(m=>m.accountId===id).map((v,j)=>({x:j+1,y:n+=v.lp}))]};});const maxX=Math.max(...series.map(s=>s.points.length-1),1),all=series.flatMap(s=>s.points.map(p=>p.y)),lo=Math.min(0,...all),hi=Math.max(1,...all),x=v=>40+v/maxX*680,y=v=>155-(v-lo)/(hi-lo)*130;return `<svg class="chart" viewBox="0 0 750 190" role="img" aria-label="Cumulative recorded LP by account, each starting at zero. Exact totals are available in Insights.">${[0,.5,1].map(t=>`<line x1="40" y1="${25+t*130}" x2="720" y2="${25+t*130}" stroke="#2c352a" stroke-dasharray="3 5"/><text x="0" y="${29+t*130}">${Math.round(hi-t*(hi-lo))}</text>`).join('')}${series.map(s=>`<polyline fill="none" stroke="${s.color}" stroke-width="2" points="${s.points.map(p=>x(p.x)+','+y(p.y)).join(' ')}"/>`).join('')}<text x="40" y="182">0</text><text x="655" y="182">${maxX} games</text></svg><div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(account(s.id)?.name)}</span>`).join('')}</div>`;}
function rankSort(a,b){const ar=rankAt(state,a),br=rankAt(state,b);return (rankScore(br.rank,br.lp??0)??-1)-(rankScore(ar.rank,ar.lp??0)??-1);}
function accountTable(list){if(!list.length)return empty('No accounts here.','Add an account to start tracking.',btn('Add account','account','','gold small'));return `<div class="table-scroll"><table><thead><tr><th>Account</th><th>Server</th><th>Rank / LP</th><th>Season W / L</th><th>Win rate</th><th>Default strategy</th><th>Sync / profiles</th></tr></thead><tbody>${list.map(a=>{const t=totals(state,a),r=rankAt(state,a),p=percent(t.wins,t.losses);return `<tr><td><div class="account-name"><span class="avatar">IV</span><div><strong>${esc(a.name)} ${state.matches.some(m=>m.accountId===a.id&&day(m.ts)===day(Date.now()))?'<span class="pill muted">Played today</span>':''} ${a.archived?'<span class="pill muted">Archived</span>':''}</strong><small>${esc(a.riotId)} · LVL ${a.level}${a.lastSync?' · synced '+date(a.lastSync):''}</small></div></div></td><td><span class="pill muted">${esc(a.region)}</span></td><td><span class="rank">${esc(r.rank)}</span><div class="help">${r.lp===null?'LP unknown':fmt(r.lp,0)+' LP'}${r.estimated?' · estimated':''}</div></td><td><span class="positive">${t.wins}</span> <span style="color:var(--muted)">/ ${t.losses}</span></td><td>${wr(p)}<span class="bar"><i style="width:${p||0}%"></i></span></td><td>${esc(nameStrategy(a.strategyId))}</td><td><div class="row-actions">${btn('↻ Sync','sync',a.id,'primary small')}${a.profile?`<a class="button secondary small" href="${esc(a.profile)}" target="_blank" rel="noopener noreferrer">OP.GG ↗</a>`:btn('＋ OP.GG','profile',a.id)}${a.porofessor?`<a class="button secondary small" href="${esc(a.porofessor)}" target="_blank" rel="noopener noreferrer">Poro ↗</a>`:''}${btn('＋ Match','match',a.id,'gold small')}${btn('Edit','account',a.id)}</div></td></tr>`;}).join('')}</tbody></table></div>`;}
function accounts(){heading('THE ENSEMBLE','One champion. <em>Many accounts.</em>','Starting balances + recorded matches · ranks follow your latest checkpoint.',btn('＋ Add account','account','','primary'));let list=state.accounts.filter(a=>(a.name+' '+a.riotId).toLowerCase().includes(search.toLowerCase()));list.sort(sort==='rank'?rankSort:sort==='wr'?(a,b)=>(percent(...Object.values(totals(state,b)))??-1)-(percent(...Object.values(totals(state,a)))??-1):(a,b)=>a.name.localeCompare(b.name));$('#content').innerHTML=`<div class="filters"><input id="account-search" class="search" aria-label="Search accounts" placeholder="Search accounts…" value="${esc(search)}"><select id="account-sort" aria-label="Sort accounts">${opt('rank','Highest rank',sort)}${opt('wr','Highest win rate',sort)}${opt('name','Account name',sort)}</select><span class="filter-hint">${list.length} accounts · ${esc(state.season)} totals</span></div>${panel('Account roster',accountTable(list),'<small>Edit an account to add both profile links</small>')}${panel('Rank checkpoints & goals',state.accounts.filter(a=>!a.archived).map(a=>{const r=rankAt(state,a),goal=rankScore(a.goalRank,a.goalLp),current=rankScore(r.rank,r.lp);const remaining=goal!==null&&current!==null?Math.max(0,goal-current):null;const sample=stats(state.matches.filter(m=>m.accountId===a.id&&m.season===state.season));const checkpoint=state.checkpoints.filter(c=>c.accountId===a.id).sort((a,b)=>b.ts-a.ts)[0];return `<div class="list-row"><div class="grow"><strong>${esc(a.name)}</strong><small>${a.goalRank?'Target: '+esc(a.goalRank)+' · '+a.goalLp+' LP'+(remaining!==null?' · '+remaining+' estimated LP to go'+(sample.lpGame>0?' · about '+Math.ceil(remaining/sample.lpGame)+' games at recorded pace':''):''):'No target set · add one in Edit'}${checkpoint?' · Latest checkpoint '+date(checkpoint.ts):''}</small></div>${btn('Set checkpoint','checkpoint',a.id)}</div>`;}).join(''))}`;}
function strategies(){heading('EXPERIMENT WITH INTENT','Your <em>strategy lab.</em>','Save your actual rune pages. Matches with the same setup can be assigned automatically.',btn('＋ New rune page / strategy','strategy','','primary'));const m=matches();$('#content').innerHTML=`<div class="notice">Comparisons use recorded games only. Different ranks, servers and patches can affect results. Small samples are exploratory.</div>${state.strategies.length?'<div class="cards">'+state.strategies.map(t=>{const s=stats(m.filter(m=>m.strategyId===t.id)),ci=interval(s.w,s.n);return `<section class="strategy-card"><span class="pill ${t.archived?'muted':''}">${t.archived?'ARCHIVED':s.n<minSample?'EARLY OBSERVATIONS':'IN STUDY'}</span><h2>${esc(t.name)}</h2><p>${esc(t.description)||'A saved setup for your Jhin games.'}</p>${runeSummary(t.runePage)}<div class="strategy-numbers"><div><strong class="positive">${wr(s.wr)}</strong><small>WIN RATE · ${s.n} GAMES</small></div><div><strong class="gold-text">${fmt(s.kda)}</strong><small>AGGREGATE KDA</small></div></div><div class="help">${s.w} wins / ${s.l} losses · ${fmt(s.csMin)} CS / min<br>95% win-rate interval: ${ci?fmt(ci[0],0)+'–'+fmt(ci[1],0)+'%':'—'}</div><div class="row-actions">${btn('Edit strategy','strategy',t.id)}${btn(t.archived?'Restore':'Archive','archive-strategy',t.id)}</div></section>`;}).join('')+'</div>':panel('Build your first experiment',empty('What will you test?','For example: a build order, a keystone, or a lane plan.<br>Each match keeps its own strategy even if the account default changes.',btn('Create a strategy','strategy','','gold')))}${panel('Comparison table',comparison(m,'strategyId'),'<small>LP metrics include only games with LP entered</small>')}`;}
function comparison(m,key){const groups=key==='accountId'?state.accounts.map(a=>[a.id,a.name]):state.strategies.map(t=>[t.id,t.name]).concat([['','Unassigned']]);const rows=groups.map(([id,name])=>({name,s:stats(m.filter(m=>m[key]===id))})).filter(x=>x.s.n).sort((a,b)=>(b.s.lpGame??-Infinity)-(a.s.lpGame??-Infinity));if(!rows.length)return empty('No comparisons yet.','Record matches to see your strategies side by side.');return `<div class="table-scroll"><table class="insights-table"><thead><tr><th>${key==='accountId'?'Account':'Strategy'}</th><th>Games</th><th>Win rate</th><th>Net LP</th><th>LP/game</th><th>LP/hour</th><th>LP coverage</th><th>Evidence</th></tr></thead><tbody>${rows.map(({name,s})=>`<tr><td>${esc(name)}</td><td>${s.n}</td><td>${wr(s.wr)}</td><td class="${s.net>=0?'positive':'negative'}">${signed(s.net)}</td><td>${signed(s.lpGame)}</td><td>${signed(s.lpHour)}</td><td>${s.lpN}/${s.n}</td><td><span class="pill muted">${s.n<minSample?'Small sample':'Compare context'}</span></td></tr>`).join('')}</tbody></table></div>`;}
function history(){heading('THE RECORD','Every shot <em>on record.</em>','Edit mistakes, preserve the details, and keep all your statistics in sync.',btn('＋ Log match','match','','primary'));const list=matches().sort((a,b)=>b.ts-a.ts),pages=Math.max(1,Math.ceil(list.length/15));page=Math.min(page,pages-1);$('#content').innerHTML=panel('Match journal',list.length?`<div class="table-scroll"><table><thead><tr><th>Result / time</th><th>Account</th><th>Strategy</th><th>LP</th><th>Lane / runes</th><th>K / D / A · CS</th><th>Time</th><th>Details</th><th>Actions</th></tr></thead><tbody>${list.slice(page*15,page*15+15).map(m=>`<tr><td><span class="pill ${m.result==='loss'?'loss':m.result==='remake'?'muted':''}">${m.result.toUpperCase()}</span><div class="help">${date(m.ts)}</div></td><td>${esc(account(m.accountId)?.name)}<div class="help">${esc(m.season)}${m.patch?' · '+esc(m.patch):''}</div></td><td>${esc(nameStrategy(m.strategyId))}<div class="help">${esc(state.sessions.find(s=>s.id===m.sessionId)?.name||'No session')}</div></td><td class="${m.lp>=0?'positive':'negative'}">${signed(m.lp)}</td><td>${esc(m.enemy||'—')}<div class="help">Support: ${esc(m.support||'—')}<br>${esc(m.keystone||'No keystone')}</div></td><td>${[m.kills,m.deaths,m.assists].map(v=>v===null?'—':v).join(' / ')}<div class="help">${m.cs===null?'—':m.cs} CS${m.cs!==null&&m.duration?' · '+fmt(m.cs/m.duration)+' / min':''}</div></td><td>${m.duration?fmt(m.duration)+'m':'—'}<div class="help">${m.queueMinutes!==null?fmt(m.queueMinutes)+'m queue':''}</div></td><td class="history-note">${esc(m.note||'—')}${m.build?'<br>Build: '+esc(m.build):''}${m.runes?'<br>Runes: '+esc(m.runes):''}</td><td><div class="row-actions">${btn('Edit','edit-match',m.id)}${btn('Delete','delete-match',m.id,'danger small')}</div></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${list.length} matches · Page ${page+1} of ${pages}</span><button class="button secondary small" data-action="prev" ${page===0?'disabled':''}>← Previous</button><button class="button secondary small" data-action="next" ${page===pages-1?'disabled':''}>Next →</button></div>`:empty('A clean page.','No matches match your filters.',btn('Log a match','match','','gold small')));}
function sessions(){heading('THE RHYTHM','Play with <em>intention.</em>','Group your games into sessions. Notice when your best performances happen.',btn('＋ Start session','session','','primary'));const list=[...state.sessions].sort((a,b)=>b.start-a.start);$('#content').innerHTML=list.length?list.map(x=>{const m=state.matches.filter(m=>m.sessionId===x.id),s=stats(m);return `<section class="panel session-card"><div class="panel-head"><div><h2>${esc(x.name)} ${x.end===null?'<span class="pill">IN PROGRESS</span>':''}</h2><div class="help">${date(x.start)}${x.end?' — '+date(x.end):''} · ${esc(x.season)}</div></div><div class="row-actions">${btn('Edit','edit-session',x.id)}${x.end===null?btn('End session','end-session',x.id,'gold small'):''}</div></div><div class="panel-body"><span>Games<strong>${s.n}</strong></span><span>W / L<strong>${s.w} / ${s.l}</strong></span><span>Net LP<strong>${signed(s.net)}</strong></span><span>LP / hour<strong>${signed(s.lpHour)}</strong></span><span>Elapsed<strong>${fmt(((x.end||Date.now())-x.start)/60000,0)} min</strong></span></div>${m.length?m.map(recentRow).join(''):empty('Session ready.','Your next match will be assigned to this session automatically.')}</section>`;}).join(''):panel('Your sessions',empty('Find your rhythm.','Start a session before you play. You can log across multiple accounts.',btn('Start session','session','','gold small')));}
function groupTable(m,key,title){const keys=[...new Set(m.map(x=>x[key]).filter(Boolean))];return panel(title,keys.length?`<div class="table-scroll"><table><thead><tr><th>${title}</th><th>Games</th><th>Win rate</th><th>Net LP</th><th>Evidence</th></tr></thead><tbody>${keys.map(k=>({k,s:stats(m.filter(x=>x[key]===k))})).sort((a,b)=>(b.s.wr??0)-(a.s.wr??0)).map(({k,s})=>`<tr><td>${esc(k)}</td><td>${s.n}</td><td>${wr(s.wr)}</td><td>${signed(s.net)}</td><td><span class="pill muted">${s.n<minSample?'Small sample':'Compare context'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('No details yet.','Add these details when recording a match.'));}
function insights(){heading('READ BETWEEN THE GAMES','Patterns, <em>not promises.</em>','Use comparable conditions and enough games before choosing your next approach.');const m=matches(),s=stats(m);$('#content').innerHTML=`<div class="filters"><label class="inline-fields">Small-sample threshold <input id="min-sample" type="number" min="1" max="1000" value="${minSample}" style="width:80px"></label><span class="filter-hint">Threshold is a display aid, not a significance test.</span></div><div class="metrics">${metric('CS PER MINUTE',fmt(s.csMin),'Games with CS and duration')}${metric('AGGREGATE KDA',fmt(s.kda),'(Total kills + assists) / deaths')}${metric('LP PER GAME',signed(s.lpGame),`${s.lpN} games with known LP`)}${metric('TRACKED WIN RATE',wr(s.wr),`${s.n} games · remakes excluded`)}</div>${panel('Accounts compared',comparison(m,'accountId'))}${panel('Strategies compared',comparison(m,'strategyId'))}<div class="grid-two">${groupTable(m,'enemy','Enemy ADC')}${groupTable(m,'support','Allied support')}</div>${groupTable(m,'keystone','Keystone')}<div class="grid-two">${panel('Cumulative win rate',`<div class="panel-body">${performanceChart(m,'wr')}</div>`)}${panel('CS per minute',`<div class="panel-body">${performanceChart(m,'cs')}</div>`)}</div>${panel('K / D / A across matches',`<div class="panel-body">${performanceChart(m,'kda')}</div>`)}<div class="notice">LP/hour uses games with both LP and duration; entered queue time is included. Rank filters require a known baseline or checkpoint at match time. Rune trees imported from the old tracker remain coarse labels. Win-rate intervals in Strategy lab use the Wilson 95% method.</div>`;}
function settings(){heading('KEEP YOUR WORK','Your data. <em>Your control.</em>','Back up regularly. Your games are stored in this browser, on this site.');$('#content').innerHTML=`<div class="notice">Champion & rune catalog: Riot Data Dragon ${esc(catalog.version)} · ${catalog.champions.length} champions. ${btn('↻ Refresh catalog','refresh-catalog')}</div><div class="settings-grid">${panel('Backups & migration',`<div class="panel-body"><p>Export a complete JSON backup, including accounts, starting balances, matches, sessions, strategies and checkpoints. Import replaces this workspace after validation and confirmation; a download of your current workspace is created first.</p><div class="row-actions">${btn('↓ Export backup','backup','','gold')}<label class="button secondary file-label">↑ Import JSON<input type="file" id="import-file" accept="application/json,.json"></label></div><div style="margin-top:15px"><a class="button secondary" href="https://github.com/h0rv404/Jhin-Tracker" target="_blank" rel="noopener noreferrer">View source on GitHub</a></div><h3>Coming from the original tracker?</h3><p>Import its saved <code>jhin_tracker_v3</code> JSON. Original account totals become starting balances after subtracting imported history. Separate manual counters are retained as a legacy archive.</p>${btn('Paste old tracker JSON','paste-import')}${state.legacyAggregates?'<div style="margin-top:14px">'+btn('Download legacy counters','legacy')+'</div>':''}${blocked?'<div class="notice red" style="margin-top:20px">Saving is paused. Download the original stored data before recovering.</div>'+btn('Download stored data','raw-backup')+' '+btn('Recover from backup','recover','','danger'):''}</div>`)}${panel('Seasons & archives',`<div class="panel-body"><p>Change the active season without deleting history. Previous matches and starting balances remain available in filters. End your active session before starting a new season.</p><form data-form="season"><label>Active season<input name="season" required maxlength="40" value="${esc(state.season)}"></label>${actions('Set season')}</form><div class="help">Archiving accounts and strategies hides them from new-entry defaults; previous records remain intact.</div></div>`)}${panel('Profile links & automatic imports',`<div class="panel-body"><p>Each account can store an OP.GG profile and a Porofessor profile. Use Edit in Accounts to add or change the links. They open in a new tab.</p><div class="step"><b>01</b><div><strong>Profile shortcuts · available</strong><br>Open your exact profile with one click.</div></div><div class="step"><b>02</b><div><strong>On-demand Riot sync · ready to connect</strong><br>Save a Riot API key securely once, then use Sync on any account. Fetch results, K/D/A, CS, duration, runes, items and current rank directly from Riot.</div></div><div class="step"><b>03</b><div><strong>One-time account setup</strong><br>Each account needs its Riot ID + #tag and server. Development API keys expire every 24 hours; a personal key can be requested from Riot for longer-term use. Historic per-game LP is not supplied and remains optional.</div></div>${btn('Connect / replace Riot API key','connect','','primary')} ${btn('Remove saved key','disconnect','','secondary')} <a href="https://developer.riotgames.com/docs/portal" target="_blank" rel="noopener noreferrer" class="text-btn">Riot developer documentation ↗</a></div>`)}${panel('Storage & interpretation',`<div class="panel-body"><p>No cloud game database is connected. Another browser, device, domain or private window has a different workspace. Export/import transfers your data.</p><p>Rank changes are estimated from your recorded LP; actual promotion, demotion and protection rules can change the result. Set a dated checkpoint when the game shows a different rank. Higher apex tiers require manual checkpoints.</p><p>Starting W/L balances are included in account tables only. Analytics use recorded matches. Unknown LP, K/D/A and time stay unknown.</p>${state.warnings?.length?'<h3>Migration notes</h3>'+state.warnings.map(w=>'<p>'+esc(w)+'</p>').join(''):''}<h3>Conflicting tabs</h3><p>If another tab changes the workspace, this tab pauses saving until you reload, so it cannot silently overwrite those changes.</p></div>`)}</div>`;}
function accountDialog(id='',profilesOnly=false){const a=account(id)||{name:'',riotId:'',region:'LAN',level:30,rank:'Unranked',lp:null,baseWins:0,baseLosses:0,baselineSeason:state.season,strategyId:'',profile:'',porofessor:'',goalRank:'',goalLp:0,archived:false};if(profilesOnly){dialog('Link your account',`<p class="subtitle" style="margin:0 0 20px">${esc(a.name)} · Profile links are shortcuts. They do not import games automatically.</p><form data-form="profile" data-id="${esc(id)}"><div class="fields">${input('profile','OP.GG profile URL',a.profile,'url','maxlength="500" placeholder="https://op.gg/lol/summoners/…" class="full"')}${input('porofessor','Porofessor profile URL',a.porofessor,'url','maxlength="500" placeholder="https://www.porofessor.gg/…"')}</div>${actions('Save profile links')}</form>`);return;}dialog(id?'Edit account':'Add an account',`<form data-form="account" data-id="${esc(id)}"><div class="form-caption">Identity & default strategy</div><div class="fields">${input('name','Account label',a.name,'text','required maxlength="150"')}${input('riotId','Riot ID (include #tag when known)',a.riotId,'text','maxlength="150"')}${select('region','Server',['LAN','LAS','NA','EUW','EUNE','KR','BR','OCE','TR','RU','JP','SEA','TW','VN','ME'].map(x=>opt(x,x,a.region)).join(''))}${input('level','Account level',a.level,'number','required min="1" max="10000" step="1"')}${select('strategyId','Default strategy',opt('','Unassigned',a.strategyId)+state.strategies.filter(t=>!t.archived||t.id===a.strategyId).map(t=>opt(t.id,t.name,a.strategyId)).join(''))}<label class="check-label"><input type="checkbox" name="archived" ${a.archived?'checked':''}> Archive account</label></div><hr class="form-separator"><div class="form-caption">Profile shortcuts</div><div class="fields">${input('profile','OP.GG profile URL',a.profile,'url','maxlength="500" placeholder="https://op.gg/…"')}${input('porofessor','Porofessor profile URL',a.porofessor,'url','maxlength="500" placeholder="https://porofessor.gg/…"')}</div><p class="help">Links open your profile. Automatic import is not connected.</p><details style="margin-top:20px"><summary>Starting balances & climb target · advanced</summary><div class="form-caption">Starting balances · not your current totals</div><div class="fields">${input('baselineSeason','Starting-balance season',a.baselineSeason,'text','required maxlength="40"')}${input('baselineTs','Starting rank timestamp',inputTime(a.baselineTs||Date.now()),'datetime-local','required')}${input('baseWins','Starting wins',a.baseWins,'number','required min="0" step="1"')}${input('baseLosses','Starting losses',a.baseLosses,'number','required min="0" step="1"')}${select('rank','Starting rank',opt('Unranked','Unranked',a.rank)+DIVISIONS.map(r=>opt(r,r,a.rank)).join(''))}${input('lp','Starting rank LP (blank = unknown)',a.lp,'number','min="0" max="100000" step="1"')}</div><p class="help">Current totals add recorded matches to these balances. To correct your current rank, use Set checkpoint in Accounts.</p><hr class="form-separator"><div class="form-caption">Climb target</div><div class="fields">${select('goalRank','Target rank',ranks(a.goalRank,'No target'))}${input('goalLp','Target LP',a.goalLp,'number','required min="0" max="100000" step="1"')}</div></details>${actions(id?'Save account':'Add account')}</form>`);}
function sessionDialog(id=''){const s=state.sessions.find(x=>x.id===id);if(!s&&state.sessions.some(x=>x.end===null)){location.hash='sessions';toast('End your active session before starting another.');return;}dialog(s?'Edit session':'Start a session',`<form data-form="session" data-id="${esc(id)}"><div class="fields"><div class="full">${input('name','Session name',s?.name||'Ranked · '+new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short'}),'text','required maxlength="100"')}</div>${input('start','Start time',inputTime(s?.start||Date.now()),'datetime-local','required')}${input('end','End time (blank = active)',s?.end?inputTime(s.end):'','datetime-local')}${input('season','Season',s?.season||state.season,'text','required maxlength="100"')}</div><p class="help">New matches default to your active session. Assign older matches by editing their session and time.</p>${actions(s?'Save session':'Start session')}</form>`);}
function checkpointDialog(id){const a=account(id),r=rankAt(state,a);dialog('Set an exact rank checkpoint',`<form data-form="checkpoint" data-id="${esc(id)}"><p class="subtitle" style="margin:0 0 20px">${esc(a.name)} · Use the rank and LP shown in the League client. This corrects future estimates without changing previous match LP.</p><div class="fields">${select('rank','Rank',DIVISIONS.map(x=>opt(x,x,r.rank)).join(''))}${input('lp','LP',r.lp??0,'number','required min="0" max="100000" step="1"')}${input('ts','Checkpoint time',inputTime(Date.now()),'datetime-local','required')}${input('season','Season',state.season,'text','required maxlength="40"')}</div>${actions('Save checkpoint')}</form>`);}
async function importData(raw,recovery=false){let parsed;try{parsed=JSON.parse(raw);}catch{throw Error('This file is not valid JSON.');}const next=parsed.version===VERSION?validate(parsed):migrate(parsed);if(!confirm(`Replace this workspace with ${next.accounts.length} accounts and ${next.matches.length} matches? A backup of the current workspace will download first.`))return false;if(recovery){download(localStorage.getItem(KEY)||localStorage.getItem('jhin_tracker_v3')||JSON.stringify(state),'jhin-before-recovery.json');}else backup();const oldBlocked=blocked;try{blocked=false;persist(next,'Workspace imported.');f.season=state.season;render();}catch(e){blocked=oldBlocked;throw e;}return true;}
function deleteMatch(id){const m=state.matches.find(m=>m.id===id);dialog('Delete this match?',`<p class="subtitle">${esc(account(m.accountId)?.name)} · ${date(m.ts)} · ${m.result}<br>The match will be removed from all calculated statistics. Undo is available after deletion.</p><div class="form-actions">${btn('Keep match','close')}${btn('Delete match','confirm-delete',id,'danger')}</div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{switch(action){case 'sync':awaitSync(id);break;case 'connect':connectDialog();break;case 'disconnect':api('/api/connection',{method:'DELETE'}).then(()=>toast('Saved Riot API key removed. Account links and matches are preserved.')).catch(e=>toast(e.message));break;case 'confirm-sync':applySync();break;case 'more-sync':awaitSync(id,true);break;case 'refresh-catalog':refreshCatalog().then(()=>{render();toast((catalog.stale?'Using bundled champion and rune snapshot ':'Champion and rune catalog updated to ')+catalog.version);}).catch(e=>toast(e.message));break;case 'pick-rune':pickRune(b);break;case 'assign-unassigned':assignDialog();break;case 'match':matchDialog('',id);break;case 'edit-match':matchDialog(id);break;case 'account':accountDialog(id);break;case 'profile':accountDialog(id,true);break;case 'strategy':strategyDialog(id);break;case 'archive-strategy':mutate(s=>{const t=s.strategies.find(t=>t.id===id);t.archived=!t.archived;},'Strategy updated.');break;case 'checkpoint':checkpointDialog(id);break;case 'session':sessionDialog();break;case 'edit-session':sessionDialog(id);break;case 'end-session':mutate(s=>{const x=s.sessions.find(x=>x.id===id);const last=Math.max(x.start,...s.matches.filter(m=>m.sessionId===id).map(m=>m.ts));x.end=Math.max(Date.now(),last);},'Session completed.');break;case 'go-sessions':location.hash='sessions';break;case 'go-accounts':location.hash='accounts';break;case 'close':$('#dialog').close();break;case 'backup':backup();break;case 'raw-backup':download(localStorage.getItem(KEY)||localStorage.getItem('jhin_tracker_v3')||'{}','jhin-stored-recovery.json');break;case 'recover':dialog('Recover your workspace',`<form data-form="paste-import" data-recovery="true">${area('json','Paste a valid Atelier backup or original tracker JSON')}<p class="help">The original stored data will download before replacement.</p>${actions('Validate & recover')}</form>`);break;case 'legacy':download(state.legacyAggregates,'jhin-legacy-counters.json');break;case 'paste-import':dialog('Import original tracker data',`<form data-form="paste-import">${area('json','Paste original tracker JSON')}<p class="help">This replaces the current workspace after confirmation. A backup will download first.</p>${actions('Validate & import')}</form>`);break;case 'delete-match':deleteMatch(id);break;case 'confirm-delete':mutate(s=>{s.matches=s.matches.filter(m=>m.id!==id);},'Match deleted; statistics recalculated.');$('#dialog').close();break;case 'undo':if(previous){const next=previous;persist(next,'Last action undone.');previous=null;$('#toast').innerHTML='<span>Last action undone.</span>';}break;case 'filters':f={season:state.season,account:'',strategy:'',region:'',patch:'',rank:'',from:'',to:''};page=0;render();break;case 'prev':page=Math.max(0,page-1);history();break;case 'next':page++;history();break;}}catch(err){const error=$('#dialog[open] .form-error');if(error)error.textContent=err.message;else toast(err.message);}});
document.addEventListener('change',async e=>{try{if(e.target.id==='rune-primary'||e.target.id==='rune-secondary'){const key=e.target.id==='rune-primary'?'primary':'secondary';const previousPrimary=runeDraft.primary;runeDraft[key]=Number(e.target.value);if(runeDraft.primary===runeDraft.secondary){runeDraft[key==='primary'?'secondary':'primary']=catalog.trees.find(t=>t.id!==runeDraft[key]).id;}const tree=catalog.trees.find(t=>t.id===runeDraft.primary);if(previousPrimary!==runeDraft.primary)runeDraft.primaryRunes=tree.slots.map(slot=>slot.runes[0].id);runeDraft.secondaryRunes=[];$('#rune-builder').innerHTML=runeBuilder();}if(e.target.dataset.shard){runeDraft.shards[Number(e.target.dataset.shard)]=Number(e.target.value);}if(e.target.dataset.filter){f[e.target.dataset.filter]=e.target.value;page=0;render();}if(e.target.id==='account-sort'){sort=e.target.value;accounts();}if(e.target.id==='min-sample'){minSample=integer(e.target.value,'Sample threshold',1,1000);insights();}if(e.target.name==='accountId'&&e.target.closest('[data-form="match"]')){const form=e.target.form,a=account(e.target.value);form.elements.strategyId.value=state.strategies.some(t=>t.id===a.strategyId&&!t.archived)?a.strategyId:'';}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Backup is too large (maximum 20 MB).');await importData(await file.text(),blocked);e.target.value='';}}catch(err){const error=$('#dialog[open] .form-error');if(error)error.textContent=err.message;else toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='account-search'){search=e.target.value;const start=e.target.selectionStart;accounts();$('#account-search').focus();$('#account-search').setSelectionRange(start,start);}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const d=Object.fromEntries(new FormData(form)),id=form.dataset.id,kind=form.dataset.form;const time=(raw,label)=>{const ts=new Date(raw).getTime();if(!Number.isFinite(ts))throw Error(`Enter a valid ${label}.`);return ts;};try{if(kind==='account'){const old=account(id),a={...(account(id)||{}),id:id||uid(),name:d.name.trim(),riotId:d.riotId.trim(),region:d.region,level:integer(d.level,'Level',1,10000),baseWins:integer(d.baseWins,'Starting wins'),baseLosses:integer(d.baseLosses,'Starting losses'),baselineSeason:d.baselineSeason.trim(),baselineTs:time(d.baselineTs,'starting rank time'),rank:d.rank,lp:integer(d.lp,'LP',0,d.rank==='Unranked'||DIVISIONS.indexOf(d.rank)<28?99:100000,true),strategyId:d.strategyId,profile:profileURL(d.profile),porofessor:profileURL(d.porofessor),goalRank:d.goalRank,goalLp:integer(d.goalLp,'Goal LP',0,100000),archived:!!d.archived};if(a.rank==='Unranked')a.lp=null;mutate(s=>{if(old)s.accounts[s.accounts.findIndex(a=>a.id===id)]=a;else s.accounts.push(a);},old?'Account saved.':'Account added.');}
else if(kind==='profile'){mutate(s=>{const a=s.accounts.find(a=>a.id===id);a.profile=profileURL(d.profile);a.porofessor=profileURL(d.porofessor);},'Profile links saved.');}
else if(kind==='strategy'){const t={id:id||uid(),name:d.name.trim(),description:(d.description||'').trim(),runePage:runeDraft?validatePage(clone(runeDraft)):null,archived:strategy(id)?.archived||false};mutate(s=>{if(id)s.strategies[s.strategies.findIndex(t=>t.id===id)]=t;else s.strategies.push(t);},'Strategy saved.');}
else if(kind==='match'){const m={...(state.matches.find(m=>m.id===id)||{}),id:id||uid(),accountId:d.accountId,strategyId:d.strategyId,sessionId:d.sessionId,result:d.result,lp:integer(d.lp,'LP change',-1000,1000,true),ts:time(d.ts,'match time'),season:d.season.trim(),patch:(d.patch||'').trim(),enemy:(d.enemy||'').trim(),support:(d.support||'').trim(),keystone:(d.keystone||'').trim(),runes:(d.runes||'').trim(),build:(d.build||'').trim(),note:(d.note||'').trim(),runePage:state.matches.find(m=>m.id===id)?.runePage||clone(strategy(d.strategyId)?.runePage||null),duration:number(d.duration,'Game duration',.1,1000,true),queueMinutes:number(d.queueMinutes,'Queue time',0,1000,true),cs:integer(d.cs,'CS',0,10000,true),kills:integer(d.kills,'Kills',0,10000,true),deaths:integer(d.deaths,'Deaths',0,10000,true),assists:integer(d.assists,'Assists',0,10000,true),matchId:(d.matchId||'').trim()};if(!id&&m.runePage){m.keystone=rune(m.runePage.primaryRunes[0])?.name||m.keystone;m.runes=pageNames(m.runePage);}
if(m.ts>Date.now()+60000)throw Error('Match time cannot be in the future.');if(!id&&state.matches.some(x=>x.accountId===m.accountId&&Math.abs(x.ts-m.ts)<60000)&&!confirm('A match for this account already exists within the same minute. Save another?'))return;mutate(s=>{if(id)s.matches[s.matches.findIndex(m=>m.id===id)]=m;else s.matches.push(m);},id?'Match corrected; all statistics updated.':'Match saved.');}
else if(kind==='session'){const x={id:id||uid(),name:d.name.trim(),season:d.season.trim(),start:time(d.start,'session start'),end:d.end?time(d.end,'session end'):null};if(x.end===null&&state.sessions.some(s=>s.end===null&&s.id!==id))throw Error('Only one session can be active at a time.');if(x.start>Date.now())throw Error('Session start cannot be in the future.');mutate(s=>{if(id)s.sessions[s.sessions.findIndex(x=>x.id===id)]=x;else s.sessions.push(x);},'Session saved.');}
else if(kind==='checkpoint'){const c={id:uid(),accountId:id,rank:d.rank,lp:integer(d.lp,'Checkpoint LP',0,DIVISIONS.indexOf(d.rank)<28?99:100000),ts:time(d.ts,'checkpoint time'),season:d.season.trim()};if(c.ts>Date.now()+60000)throw Error('Checkpoint cannot be in the future.');if(c.ts<account(id).baselineTs)throw Error('Checkpoint must be on or after the account starting rank timestamp.');mutate(s=>s.checkpoints.push(c),'Rank checkpoint saved.');}
else if(kind==='connection'){await api('/api/connection',{method:'POST',body:JSON.stringify({key:d.key})});form.reset();connectionStatus={connected:true};toast('Riot API key encrypted and saved on the server.');}
else if(kind==='link-account'){mutate(s=>{const a=s.accounts.find(a=>a.id===id);a.riotId=d.riotId.trim();a.region=d.region;},'Account identity saved.');$('#dialog').close();awaitSync(id);return;}
else if(kind==='assign-unassigned'){const ids=new Set(matches().filter(m=>!m.strategyId).map(m=>m.id));mutate(s=>{for(const m of s.matches)if(ids.has(m.id)){m.strategyId=d.strategyId;}},'Strategy assigned to selected unassigned matches.');}
else if(kind==='season'){if(state.sessions.some(s=>s.end===null))throw Error('End the active session before changing seasons.');mutate(s=>{s.season=d.season.trim();},'Season updated; history preserved.');f.season=state.season;render();return;}
else if(kind==='paste-import'){if(!await importData(d.json,form.dataset.recovery==='true'))return;}
$('#dialog').close();}catch(err){const target=form.querySelector('.form-error');if(target)target.textContent=err.message;else toast(err.message);}});
window.addEventListener('hashchange',()=>{page=0;render();window.scrollTo(0,0);});window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){blocked=true;$('#save-status').textContent='Another tab changed this data';toast('Another tab changed the workspace. Reload this tab before editing.');}});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});render();
function performanceChart(list,kind){const m=[...list].filter(m=>m.result!=='remake').sort((a,b)=>a.ts-b.ts);if(!m.length)return empty('Nothing to plot yet.','Record matches with performance details to reveal the pattern.');const colors=['#b3d786','#ddc48a','#8dbcc1','#c09dc9','#e4a48d','#a8b7e3'];let series=[];if(kind==='kda'){series=['kills','deaths','assists'].map((key,i)=>({name:key,color:colors[i],p:m.map((v,j)=>({x:j+1,y:v[key]})).filter(p=>p.y!==null)}));}else{series=[...new Set(m.map(x=>x.accountId))].map((id,i)=>{let w=0,n=0;return {name:account(id)?.name,color:colors[i%colors.length],p:m.filter(x=>x.accountId===id).map((v,j)=>{n++;if(v.result==='win')w++;return {x:j+1,y:kind==='wr'?100*w/n:v.cs!==null&&v.duration?v.cs/v.duration:null};}).filter(p=>p.y!==null)};});}series=series.filter(s=>s.p.length);if(!series.length)return empty('Details make the difference.','Add CS and duration or K/D/A when logging your games.');const points=series.flatMap(s=>s.p),maxX=Math.max(1,...points.map(p=>p.x)),hi=kind==='wr'?100:Math.max(1,...points.map(p=>p.y))*1.1,x=v=>40+(v-1)/Math.max(1,maxX-1)*680,y=v=>155-v/hi*130;return `<svg class="chart" viewBox="0 0 750 190" role="img" aria-label="${kind==='wr'?'Cumulative win rate per account':kind==='cs'?'CS per minute per account':'Kills, deaths and assists in chronological match order'}; missing values excluded">${[0,.5,1].map(t=>`<line x1="40" y1="${25+t*130}" x2="720" y2="${25+t*130}" stroke="#2c352a" stroke-dasharray="3 5"/><text x="0" y="${29+t*130}">${fmt(hi*(1-t),0)}${kind==='wr'?'%':''}</text>`).join('')}${series.map(s=>`<polyline fill="none" stroke="${s.color}" stroke-width="2" points="${s.p.map(p=>x(p.x)+','+y(p.y)).join(' ')}"/>${s.p.map(p=>`<circle cx="${x(p.x)}" cy="${y(p.y)}" r="3" fill="${s.color}"><title>${esc(s.name)} · game ${p.x}: ${fmt(p.y)}</title></circle>`).join('')}`).join('')}<text x="40" y="182">Game 1</text><text x="655" y="182">Game ${maxX}</text></svg><div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.name)}</span>`).join('')}</div>`;}
function championSelect(name,label,value=''){const choices=catalog.champions.map(c=>opt(c.name,c.name,value)).join('');return select(name,label,opt('','Not recorded',value)+(value&&!catalog.champions.some(c=>c.name===value)?opt(value,value,value):'')+choices);}
function pageNames(p){if(!p)return '';return [...p.primaryRunes,...p.secondaryRunes].map(id=>rune(id)?.name||String(id)).concat((p.shards||[]).map(id=>SHARDS[id]||String(id))).join(' · ');}
function runeSummary(p){if(!p)return '<div class="help">No saved rune page yet. Edit to choose your runes.</div>';return `<div class="rune-summary">${[...p.primaryRunes,...p.secondaryRunes].map(id=>{const r=rune(id);return r?`<img src="https://ddragon.leagueoflegends.com/cdn/img/${esc(r.icon)}" alt="${esc(r.name)}" title="${esc(r.name)}" loading="lazy">`:`<span class="pill muted">${id}</span>`;}).join('')}</div><div class="help">${esc((p.shards||[]).map(id=>SHARDS[id]||id).join(' · '))}</div>`;}
function runeBuilder(){const p=runeDraft,main=catalog.trees.find(t=>t.id===p.primary),secondary=catalog.trees.find(t=>t.id===p.secondary);const strip=s=>s.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();const choice=(r,mode,slot,selected)=>`<button type="button" data-action="pick-rune" data-mode="${mode}" data-slot="${slot}" data-rune="${r.id}" class="rune-choice ${selected?'selected':''}" aria-pressed="${selected}" title="${esc(strip(r.shortDesc||r.longDesc||''))}"><img src="https://ddragon.leagueoflegends.com/cdn/img/${esc(r.icon)}" alt="" loading="lazy"><span>${esc(r.name)}</span></button>`;return `<div class="rune-columns"><div><label>Primary tree<select id="rune-primary">${catalog.trees.map(t=>opt(t.id,t.name,p.primary)).join('')}</select></label>${main.slots.map((slot,i)=>`<fieldset class="rune-row"><legend>${i===0?'Keystone':'Primary row '+i}</legend>${slot.runes.map(r=>choice(r,'primary',i,p.primaryRunes[i]===r.id)).join('')}</fieldset>`).join('')}</div><div><label>Secondary tree<select id="rune-secondary">${catalog.trees.map(t=>opt(t.id,t.name,p.secondary)).join('')}</select></label><p class="help">Pick two runes from different rows.</p>${secondary.slots.slice(1).map((slot,i)=>`<fieldset class="rune-row"><legend>Secondary row ${i+1}</legend>${slot.runes.map(r=>choice(r,'secondary',i+1,p.secondaryRunes.includes(r.id))).join('')}</fieldset>`).join('')}<div class="shards">${SHARD_ROWS.map((row,i)=>`<label>${['Offense','Flex','Defense'][i]} shard<select data-shard="${i}">${row.map(id=>opt(id,SHARDS[id],p.shards[i])).join('')}</select></label>`).join('')}</div></div></div>`;}
function pickRune(b){const id=Number(b.dataset.rune),slot=Number(b.dataset.slot);if(b.dataset.mode==='primary')runeDraft.primaryRunes[slot]=id;else {const tree=catalog.trees.find(t=>t.id===runeDraft.secondary),sameRow=tree.slots[slot].runes.map(r=>r.id);if(runeDraft.secondaryRunes.includes(id))runeDraft.secondaryRunes=runeDraft.secondaryRunes.filter(x=>x!==id);else {runeDraft.secondaryRunes=runeDraft.secondaryRunes.filter(x=>!sameRow.includes(x));if(runeDraft.secondaryRunes.length===2)runeDraft.secondaryRunes.shift();runeDraft.secondaryRunes.push(id);}}$('#rune-builder').innerHTML=runeBuilder();}
function strategyDialog(id=''){const t=strategy(id)||{name:'',description:''},main=catalog.trees.find(t=>t.key==='Precision')||catalog.trees[0],secondary=catalog.trees.find(t=>t.key==='Sorcery')||catalog.trees.find(t=>t.id!==main.id);runeDraft=clone(t.runePage||{primary:main.id,secondary:secondary.id,primaryRunes:main.slots.map(slot=>slot.runes[0].id),secondaryRunes:[],shards:[5008,5008,5001]});dialog(id?'Edit rune page / strategy':'Save a rune page & strategy',`<form data-form="strategy" data-id="${esc(id)}">${input('name','Page / strategy name',t.name,'text','required maxlength="100" placeholder="e.g. Fleet · safe lane"')}<p class="help">Choose your exact in-game setup. New synced games can match this page automatically when its runes and shards are identical.</p><div id="rune-builder">${runeBuilder()}</div><details><summary>Optional strategy notes</summary>${area('description','What are you testing?',t.description)}</details>${actions('Save rune page')}</form>`);}
function matchDialog(id='',accountId=''){const existing=state.matches.find(m=>m.id===id),a=account(existing?.accountId||accountId)||state.accounts.find(a=>!a.archived);if(!a){toast('Add an account first.');return;}const active=state.sessions.find(s=>s.end===null&&s.season===state.season),m=existing||{accountId:a.id,strategyId:a.strategyId,sessionId:active?.id||'',result:'win',lp:null,ts:Date.now(),season:state.season,patch:catalog.version.split('.').slice(0,2).join('.'),enemy:'',support:'',keystone:'',runes:'',build:'',note:'',duration:null,queueMinutes:null,cs:null,kills:null,deaths:null,assists:null,matchId:''};dialog(existing?'Edit match':'Quick match entry',`<div class="notice">${existing&&m.source==='riot'?'Imported from Riot. Performance fields are already filled.':'Prefer automatic entry? Use ↻ Sync beside your account to fetch recent games.'}</div><form data-form="match" data-id="${esc(id)}"><div class="fields">${select('accountId','Account',state.accounts.filter(a=>!a.archived||a.id===m.accountId).map(a=>opt(a.id,`${a.name} · ${a.region}`,m.accountId)).join(''))}${select('result','Result',opt('win','Victory',m.result)+opt('loss','Defeat',m.result)+opt('remake','Remake',m.result))}${select('strategyId','Saved rune page / strategy',opt('','Unassigned',m.strategyId)+state.strategies.filter(t=>!t.archived||t.id===m.strategyId).map(t=>opt(t.id,t.name,m.strategyId)).join(''))}${input('lp','LP change · optional',m.lp,'number','min="-1000" max="1000" step="1"')}</div>${existing&&m.runePage?runeSummary(m.runePage):''}<details ${existing?'open':''} style="margin-top:18px"><summary>Lane & performance · optional</summary><div class="fields">${championSelect('enemy','Enemy bot champion',m.enemy)}${championSelect('support','Allied support',m.support)}${input('kills','Kills',m.kills,'number','min="0" max="10000" step="1"')}${input('deaths','Deaths',m.deaths,'number','min="0" max="10000" step="1"')}${input('assists','Assists',m.assists,'number','min="0" max="10000" step="1"')}${input('cs','Total CS',m.cs,'number','min="0" max="10000" step="1"')}${input('duration','Game duration (minutes)',m.duration,'number','min="0.1" max="1000" step="0.1"')}${input('queueMinutes','Queue time (minutes)',m.queueMinutes,'number','min="0" max="1000" step="0.1"')}</div></details><details style="margin-top:18px"><summary>Time, session & review · optional</summary><div class="fields">${input('ts','Match time',inputTime(m.ts),'datetime-local','required')}${select('sessionId','Session',opt('','No session',m.sessionId)+state.sessions.map(s=>opt(s.id,s.name,m.sessionId)).join(''))}${input('season','Season',m.season,'text','required maxlength="40"')}${input('patch','Patch',m.patch,'text','maxlength="150"')}${input('keystone','Keystone (filled from a saved page)',m.keystone,'text','maxlength="150"')}${input('runes','Other runes',m.runes,'text','maxlength="5000"')}${input('build','Build / items',m.build,'text','maxlength="5000"')}${input('matchId','External match ID',m.matchId,'text','maxlength="150"')}${area('note','Review note',m.note,'class="full"')}</div></details><p class="help">Only account and result are needed. All other details are optional. Champion list: Data Dragon ${esc(catalog.version)}.</p>${actions(existing?'Save corrections':'Save match')}</form>`);}
async function api(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let body;try{body=await r.json();}catch{throw Error('The server could not answer. Reload the private tracker and try again.');}if(!r.ok){const e=new Error(body.error||'Request failed.');e.status=r.status;throw e;}return body;}
function connectDialog(){dialog('Connect Riot once',`<p class="subtitle" style="margin:0 0 18px">Riot supplies the match data used by stats sites. Save your API key here, then press Sync beside an account. Your key is encrypted on the server and excluded from backups and source code.</p><form data-form="connection">${input('key','Riot API key (not your password)','','password','required autocomplete="off" placeholder="RGAPI-…" minlength="26" maxlength="110"')}<p class="help">Development keys expire every 24 hours. For ongoing personal use, apply for a personal key. You will not need to relink each account when you replace the key.</p><a class="text-btn" href="https://developer.riotgames.com/" target="_blank" rel="noopener noreferrer">Get a key from Riot’s developer portal ↗</a>${actions('Save encrypted key')}</form>`);}
function linkDialog(a){dialog('Link this account to Riot',`<p class="subtitle" style="margin:0 0 18px">Set this once for ${esc(a.name)}. Your display nickname alone may not be the complete Riot ID.</p><form data-form="link-account" data-id="${esc(a.id)}"><div class="fields">${input('riotId','Riot ID including #tag',a.riotId,'text','required maxlength="150" placeholder="Name#TAG"')}${select('region','Server',['LAN','LAS','NA','EUW','EUNE','KR','BR','OCE','TR','RU','JP','SEA','TW','VN','ME'].map(x=>opt(x,x,a.region)).join(''))}</div>${actions('Link & fetch matches')}</form>`);}
async function awaitSync(id,older=false){if(blocked){toast('Saving is paused. Reload or recover the workspace before syncing.');return;}if(syncBusy){toast('An account is already syncing.');return;}const a=account(id);if(!a.riotId.includes('#')){linkDialog(a);return;}syncBusy=true;toast('Fetching recent ranked Jhin games from Riot…');try{const body=await api('/api/sync',{method:'POST',body:JSON.stringify({riotId:a.riotId,region:a.region,puuid:a.puuid||'',offset:older?a.historyCursor||10:0,known:state.matches.filter(m=>m.accountId===id&&m.matchId).map(m=>m.matchId).slice(-500)})});syncPending={accountId:id,body,older};const candidates=body.matches.filter(m=>!state.matches.some(x=>x.accountId===id&&x.matchId===m.matchId));dialog('Review fetched matches',`<div class="sync-summary"><span class="pill">RIOT API</span><h3>${esc(body.riotId)}</h3><p class="subtitle">${esc(body.rank)} · ${fmt(body.lp)} LP · ${body.wins===null?'Unranked':body.wins+'W / '+body.losses+'L'}<br>${candidates.length} Jhin games available to import${body.hasMore?' · more history can be loaded after saving':''}.</p></div>${body.warnings.length?'<div class="notice">'+body.warnings.map(esc).join('<br>')+'</div>':''}${candidates.length?'<div class="sync-matches">'+candidates.map(m=>`<div class="list-row"><span class="result-icon ${m.result==='loss'?'loss':''}">${m.result==='win'?'W':m.result==='loss'?'L':'R'}</span><div class="grow"><strong>${m.kills} / ${m.deaths} / ${m.assists} · ${m.cs} CS</strong><small>${date(m.ts)} · ${fmt(m.duration)} min · ${esc(championName(m.enemy)||'Lane unknown')}</small></div><span class="pill muted">${esc(rune(m.keystoneId)?.name||'Runes imported')}</span></div>`).join('')+'</div>':'<div class="empty">No new Jhin games in this batch.</div>'}<p class="help">Rank, total W/L, runes, items and match performance update automatically. Riot does not supply historical per-game LP changes here; these stay blank. Similar manual entries are reconciled by time and outcome. Importing is reversible with Undo.</p><div class="form-error" role="alert"></div><div class="form-actions">${btn('Cancel','close')}${btn('Import & update account','confirm-sync','','primary')}</div>`);}catch(e){if(e.status===428){connectDialog();}else{toast(e.message);}}finally{syncBusy=false;}}
function applySync(){if(!syncPending)return;const {accountId,body,older}=syncPending;mutate(s=>{mergeAccountSync(s,accountId,body,catalog,uid);},'Matches imported and account refreshed.');$('#dialog').close();const id=syncPending.accountId;const more=body.hasMore;syncPending=null;if(more)dialog('Account updated',`<p class="subtitle">This batch is saved. To catch up after a longer break, load ten older ranked games at a time. Already imported match IDs are skipped.</p><div class="form-actions">${btn('Done','close')}${btn('Fetch older games','more-sync',id,'gold')}</div>`);}
function assignDialog(){const n=matches().filter(m=>!m.strategyId).length;if(!n){toast('No unassigned matches in the current selection.');return;}if(!state.strategies.length){strategyDialog();return;}dialog(`Assign ${n} unassigned matches`, `<form data-form="assign-unassigned"><p class="subtitle" style="margin-bottom:18px">Applies to unassigned matches in the current filters. Existing assignments and imported rune snapshots stay intact.</p>${select('strategyId','Strategy',state.strategies.filter(t=>!t.archived).map(t=>opt(t.id,t.name,'')).join(''))}${actions('Assign strategy')}</form>`);}
// Catalog refresh requires no Riot API key. The bundled snapshot keeps selectors usable offline.
refreshCatalog().then(()=>{if(!$('#dialog').open)render();}).catch(()=>{});
function checkpointChart(){if(f.strategy)return empty('No per-match LP recorded.','Current-rank snapshots cover the whole account, so they are not attributed to one strategy.');const list=state.checkpoints.filter(c=>c.rank!=='Unranked'&&c.lp!==null&&(!f.account||c.accountId===f.account)&&(!f.season||c.season===f.season)&&(!f.region||account(c.accountId)?.region===f.region)&&(!f.from||c.ts>=new Date(f.from+'T00:00:00').getTime())&&(!f.to||c.ts<=new Date(f.to+'T23:59:59.999').getTime())).sort((a,b)=>a.ts-b.ts);if(!list.length)return empty('Your climb, without extra typing.','Sync an account to capture a verified rank snapshot. Future syncs will show how your rank changed.');const colors=['#b3d786','#ddc48a','#8dbcc1','#c09dc9'],groups=[...new Set(list.map(c=>c.accountId))].map((id,i)=>{const points=list.filter(c=>c.accountId===id);const start=rankScore(points[0].rank,points[0].lp);return {id,color:colors[i%colors.length],points:points.map(c=>({...c,value:rankScore(c.rank,c.lp)-start}))};});const low=Math.min(0,...groups.flatMap(g=>g.points.map(c=>c.value))),high=Math.max(1,...groups.flatMap(g=>g.points.map(c=>c.value))),t0=list[0].ts,t1=list.at(-1).ts,x=t=>40+(t-t0)/Math.max(1,t1-t0)*680,y=v=>155-(v-low)/(high-low)*130;return `<svg class="chart" viewBox="0 0 750 190" role="img" aria-label="Verified rank change since the first snapshot for each account, expressed in division-equivalent LP">${[0,.5,1].map(t=>`<line x1="40" y1="${25+t*130}" x2="720" y2="${25+t*130}" stroke="#2c352a" stroke-dasharray="3 5"/><text x="0" y="${29+t*130}">${Math.round(high-t*(high-low))}</text>`).join('')}${groups.map(g=>`<polyline fill="none" stroke="${g.color}" stroke-width="2" points="${g.points.map(p=>x(p.ts)+','+y(p.value)).join(' ')}"/>${g.points.map(p=>`<circle cx="${x(p.ts)}" cy="${y(p.value)}" r="3" fill="${g.color}"><title>${esc(account(g.id)?.name)} · ${esc(p.rank)} ${p.lp} LP · ${date(p.ts)}</title></circle>`).join('')}`).join('')}<text x="40" y="182">${date(t0)}</text><text x="610" y="182">${date(t1)}</text></svg><div class="legend">${groups.map(g=>`<span><i style="background:${g.color}"></i>${esc(account(g.id)?.name)}</span>`).join('')}</div><p class="help">Verified rank change since each account’s first snapshot. This is not per-match LP or hidden MMR.</p>`;}
